' OR size = \'28\' THEN final_quantity ELSE 0 END), 0) AS XS_units, COALESCE(SUM(CASE WHEN size = \'S\' OR size = \'30\' THEN final_quantity ELSE 0 END), 0) AS S_units, COALESCE(SUM(CASE WHEN size = \'M\' OR size = \'32\' THEN final_quantity ELSE 0 END), 0) AS M_units, COALESCE(SUM(CASE WHEN size = \'L\' OR size = \'34\' THEN final_quantity ELSE 0 END), 0) AS L_units, COALESCE(SUM(CASE WHEN size = \'XL\' OR size = \'36\' THEN final_quantity ELSE 0 END), 0) AS XL_units, COALESCE(SUM(CASE WHEN size IN (\'XXL\', \'XXl\', \'2XL\', \'38\') THEN final_quantity ELSE 0 END), 0) AS XXL_units, COALESCE(SUM(CASE WHEN size = \'3XL\' OR size = \'40\' THEN final_quantity ELSE 0 END), 0) AS XL3_units, COALESCE(SUM(CASE WHEN size = \'4XL\' OR size = \'42\' THEN final_quantity ELSE 0 END), 0) AS XL4_units, COALESCE(SUM(CASE WHEN size = \'5XL\' OR size = \'44\' THEN final_quantity ELSE 0 END), 0) AS XL5_units, COALESCE(SUM(CASE WHEN size = \'6XL\' OR size = \'46\' THEN final_quantity ELSE 0 END), 0) AS XL6_units, COALESCE(SUM(CASE WHEN size = \'7XL\' OR size = \'48\' THEN final_quantity ELSE 0 END), 0) AS XL7_units, COALESCE(SUM(CASE WHEN size = \'8XL\' OR size = \'50\' THEN final_quantity ELSE 0 END), 0) AS XL8_units FROM snitch_final_inventory_wh2 GROUP BY 1 ), PivotTable AS ( Select trim(upper(sku_group)) as sku_group, sum(Sellable_Inventory) as Sellable_Inventory, sum(XS_units) as XS_units, sum(S_units) as S_units, sum(M_units) as M_units, sum(L_units) as L_units, sum(XL_units) as XL_units, sum(XXL_units) as XXL_units, sum(XL3_units) as XL3_units, sum(XL4_units) as XL4_units, sum(XL5_units) as XL5_units, sum(XL6_units) as XL6_units, sum(XL7_units) as XL7_units, sum(XL8_units) as XL8_units, sum(NA_units) as NA_units from pivot_table_pre where lower(sku_group) not like\'cb%\' GROUP BY SKU_GROUP ), eoq_test_pre as ( select upper(trim(sku_group)) as sku_group, product_name, first_order_date, avg(final_ros) as final_ros, avg(eoq_new) as eoq_new, avg(total_units_on_hand) as total_units_on_hand, avg(op) as op, avg(natural_ros) as natural_ros, avg(sales_last_7_days) as sales_last_7_days, avg(sales_last_15_days) as sales_last_15_days, avg(sales_last_30_days) as sales_last_30_days from snitch_db.maplemonk.EOQ_Test where product_name is not null or product_name != \'\' group by 1,2,3 ) select coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group) as sku_group, product.id, price.original_price as price, price.current_slashed_price, product.product_name, case when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSS\' then \'Shirts\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MST\' then \'T-Shirts\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSD\' then \'Jeans\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSW\' then \'Sweaters\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSO\' then \'Cargo Pants\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSK\' then \'Jackets\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MCR\' then \'Shirts\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSR\' then \'Trousers\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),6) = \'4MBGSS\' then \'Shirts\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),6) = \'4MBGSD\' then \'Jeans\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MTR\' then \'Cargo Pants\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSN\' then \'Shirts\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),2) = \'SN\' then \'Sunglasses\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),2) = \'SH\' then \'Shoes\' else product.category end as category, EOQ_Test.final_ros, round(sum(coalesce(EOQ_Test.eoq_new,0)),0) as total_eoq, round(sum(coalesce(PivotTable.Sellable_Inventory,EOQ_Test.total_units_on_hand)),0) as available_units, round(sum(coalesce(EOQ_Test.op,0)),0) as order_point, EOQ_Test.natural_ros, EOQ_Test.sales_last_7_days, EOQ_Test.sales_last_15_days, EOQ_Test.sales_last_30_days, CASE WHEN EOQ_Test.final_ros >= 15 THEN \'1-Head\' WHEN EOQ_Test.final_ros < 15 AND EOQ_Test.final_ros >= 5 THEN \'2-Belly\' WHEN EOQ_Test.first_order_date > cast(getdate() as date)-45 THEN \'4-New\' WHEN EOQ_Test.first_order_date is not null and EOQ_Test.final_ros <5 then \'3-Tail\' WHEN EOQ_Test.first_order_date is null and product.status = \'active\' then \'4-New-Not-Sold\' WHEN EOQ_Test.first_order_date is null and product.status = \'draft\' then \'Draft\' WHEN product.status is null then \'Not-Cataloged\' ELSE \'Others\' END AS sku_class, PivotTable.Sellable_inventory, PivotTable.XS_units, PivotTable.S_units, PivotTable.M_units, PivotTable.L_units, PivotTable.XL_units, PivotTable.XXL_units, PivotTable.XL3_units, PivotTable.XL4_units, PivotTable.XL5_units, PivotTable.XL6_units, PivotTable.XL7_units, PivotTable.XL8_units, PivotTable.NA_units, (CASE WHEN PivotTable.XS_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.S_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.M_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.L_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XXL_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL3_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL4_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL5_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL6_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL7_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL8_units > 0 THEN 1 ELSE 0 END) AS num_size_available, product.status, product.live_date, \'North\' as Warehouse_Location from PivotTable full outer join eoq_test_pre as EOQ_Test on PivotTable.sku_group = EOQ_Test.sku_group left join live_date_final as product on coalesce(PivotTable.sku_group,EOQ_Test.sku_group) = product.sku_group left join price as price on coalesce(PivotTable.sku_group,EOQ_Test.sku_group) = price.sku_group where COALESCE(PivotTable.SKU_GROUP, EOQ_Test.sku_group) != \'TEST_SNITCH\' and COALESCE(PivotTable.SKU_GROUP, EOQ_Test.sku_group) != \'GIFT\' group by COALESCE(PivotTable.SKU_GROUP, EOQ_Test.sku_group), product.id, price.original_price, price.current_slashed_price, product.product_name, product.category, EOQ_Test.final_ros, EOQ_Test.natural_ros, EOQ_Test.sales_last_7_days, EOQ_Test.sales_last_15_days, EOQ_Test.sales_last_30_days, EOQ_Test.first_order_date, product.status, PivotTable.Sellable_inventory, PivotTable.XS_units, PivotTable.S_units, PivotTable.M_units, PivotTable.L_units, PivotTable.XL_units, PivotTable.XXL_units, PivotTable.XL3_units, PivotTable.XL4_units, PivotTable.XL5_units, PivotTable.XL6_units, PivotTable.XL7_units, PivotTable.XL8_units, PivotTable.NA_units, product.live_date ) ; create or replace table snitch_db.maplemonk.availability_master_v2_Merged as select * from snitch_db.maplemonk.availability_master_v2_North union all select * from snitch_db.maplemonk.AVAILABILITY_MASTER_V2_SOUTH ; CREATE OR REPLACE TABLE outward_options_offline AS WITH BASE AS ( SELECT BRANCH_CODE, MARKETPLACE_MAPPED, UPPER(SKU_GROUP) AS SKU_GROUP, INVENTORY, JIT_QTY, (XS_UNITS + JIT_XS_UNITS) AS TTL_XS, (S_UNITS + JIT_S_UNITS) AS TTL_S, (M_UNITS + JIT_M_UNITS) AS TTL_M, (L_UNITS + JIT_L_UNITS) AS TTL_L, (XL_UNITS + JIT_XL_UNITS) AS TTL_XL, (XXL_UNITS + JIT_2XL_UNITS) AS TTL_XXL, (XL3_UNITS + JIT_3XL_UNITS) AS TTL_3XL, (XL4_UNITS + JIT_4XL_UNITS) AS TTL_4XL, (XL5_UNITS + JIT_5XL_UNITS) AS TTL_5XL, (XL6_UNITS + JIT_6XL_UNITS) AS TTL_6XL, NEW_CATEGORY, STYLE, NUM_SIZE_AVAILABLE, FRESH_INVENTORY FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER WHERE UPPER(NEW_CATEGORY) NOT IN (\'BAGS\',\'BELTS\',\'PERFUMES\',\'SHOES\',\'SUNGLASSES\') AND NEW_CATEGORY IS NOT NULL AND BRANCH_CODE IS NOT NULL AND UPPER(MARKETPLACE_MAPPED) NOT IN ( \'SNITCH - WH - B2B\',\'SNITCH - WH - SR\',\'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - SNITCH X\',\'SNITCH - WH - RAJASTHAN\',\'SNITCH - WH - U.P\', \'SNITCH - WH - M P\',\'SNITCH - WH - GUJARAT\' ) ), CUT_SIZE_FLAGS AS ( SELECT BRANCH_CODE, NEW_CATEGORY, SKU_GROUP, CASE WHEN UPPER(SKU_GROUP) LIKE \'4MBG%\' AND ( (CASE WHEN TTL_XS > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_S > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_M > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_L > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_XL > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_XXL > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_3XL > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_4XL > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_5XL > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_6XL > 0 THEN 1 ELSE 0 END) ) < 4 THEN \'YES\' WHEN UPPER(SKU_GROUP) NOT LIKE \'4MBG%\' AND ( (CASE WHEN TTL_S > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_M > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_L > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_XL > 0 THEN 1 ELSE 0 END) ) < 4 THEN \'YES\' ELSE \'NO\' END AS CUT_SIZE FROM BASE ), FULL_ONLY AS ( SELECT DISTINCT BRANCH_CODE, NEW_CATEGORY, SKU_GROUP FROM CUT_SIZE_FLAGS WHERE CUT_SIZE = \'NO\' ), FRESH_OPTS AS ( SELECT DISTINCT b.BRANCH_CODE, b.NEW_CATEGORY, b.SKU_GROUP FROM BASE b JOIN CUT_SIZE_FLAGS c ON c.BRANCH_CODE = b.BRANCH_CODE AND c.NEW_CATEGORY = b.NEW_CATEGORY AND c.SKU_GROUP = b.SKU_GROUP WHERE c.CUT_SIZE = \'YES\' AND b.INVENTORY > 0 AND b.INVENTORY = b.FRESH_INVENTORY ), AGG AS ( SELECT x.BRANCH_CODE, x.NEW_CATEGORY, COUNT(DISTINCT fo.SKU_GROUP) AS full_only_options, COUNT(DISTINCT fr.SKU_GROUP) AS fresh_options_in_cutsize FROM ( SELECT DISTINCT BRANCH_CODE, NEW_CATEGORY FROM FULL_ONLY UNION SELECT DISTINCT BRANCH_CODE, NEW_CATEGORY FROM FRESH_OPTS ) x LEFT JOIN FULL_ONLY fo ON fo.BRANCH_CODE = x.BRANCH_CODE AND fo.NEW_CATEGORY = x.NEW_CATEGORY LEFT JOIN FRESH_OPTS fr ON fr.BRANCH_CODE = x.BRANCH_CODE AND fr.NEW_CATEGORY = x.NEW_CATEGORY GROUP BY x.BRANCH_CODE, x.NEW_CATEGORY ) SELECT b.branch_name, b.branch_code, b.category, b.base_stock, b.category_mix, b.ideal_option_count, ROUND(b.ideal_option_count * 1.05) AS to_be_maintained_option_count, b.total_skus, COALESCE(a.full_only_options, 0) AS full_only_options, COALESCE(a.fresh_options_in_cutsize, 0) AS fresh_options_in_cutsize, GREATEST( b.total_skus - COALESCE(a.full_only_options, 0) - COALESCE(a.fresh_options_in_cutsize, 0), 0 ) AS outward_options, b.total_skus - GREATEST( b.total_skus - COALESCE(a.full_only_options, 0) - COALESCE(a.fresh_options_in_cutsize, 0), 0 ) AS final_SKUs FROM SNITCH_DB.MAPLEMONK.STORE_CATEGORY_DELTA AS b LEFT JOIN AGG a ON a.BRANCH_CODE = b.BRANCH_CODE AND a.NEW_CATEGORY = b.CATEGORY ORDER BY b.branch_code, b.category; CREATE OR REPLACE TABLE offline_future_inwards AS With actual_pre as ( SELECT UPPER(TRIM(REVERSE(SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\") )))) AS sku_group, MAX(DATE_TRUNC(\'day\', \"PUTAWAY_UPDATED\"::date)) AS putaway_updated, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS putaway_completed_quantity FROM snitch_db.maplemonk.putaway_tracking WHERE \"PUTAWAY_UPDATED\" >= current_date -30 AND LOWER(FINAL_TYPE) = \'new inward\' GROUP BY 1 HAVING SUM(\"PUTAWAY_COMPLETED_QUANTITY\") > 100 ORDER BY putaway_updated DESC, sku_group), actual_plan AS ( SELECT a.sku_group, COALESCE( CASE WHEN LOWER(a.sku_group) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(a.sku_group) LIKE \'r4mbg%\' THEN \'plus_size\' WHEN LOWER(b.style) LIKE \'%luxe%\' THEN \'luxe\' WHEN LOWER(b.style) LIKE \'%core%\' THEN \'core\' WHEN LOWER(b.category) IN (\'perfumes\',\'accessories\',\'bags\',\'belts\',\'sunglasses\',\'shoes\',\'slip-ons\') THEN \'long_tail\' END, CASE WHEN UPPER(a.sku_group) LIKE \'4MSWHC%\' THEN \'core\' WHEN UPPER(a.sku_group) LIKE \'4MSWC%\' THEN \'core\' WHEN UPPER(a.sku_group) LIKE \'4MSKC%\' THEN \'core\' WHEN UPPER(a.sku_group) LIKE \'4MCRD%\' THEN \'core\' WHEN UPPER(a.sku_group) LIKE \'4MCRT%\' THEN \'core\' WHEN UPPER(a.sku_group) LIKE \'4MLRT%\' THEN \'luxe\' WHEN UPPER(a.sku_group) LIKE \'4MLXT%\' THEN \'luxe\' WHEN UPPER(a.sku_group) LIKE \'4MLXD%\' THEN \'luxe\' WHEN UPPER(a.sku_group) LIKE \'4MBGSS%\' THEN \'plus_size\' WHEN UPPER(a.sku_group) LIKE \'4MBGSR%\' THEN \'plus_size\' WHEN UPPER(a.sku_group) LIKE \'4MBGSD%\' THEN \'plus_size\' WHEN UPPER(a.sku_group) LIKE \'4MBGST%\' THEN \'plus_size\' WHEN UPPER(a.sku_group) LIKE \'SH00%\' THEN \'long_tail\' WHEN UPPER(a.sku_group) LIKE \'4MBL%\' THEN \'long_tail\' END, \'Snitch\' ) AS l1_category, COALESCE( b.category, CASE WHEN UPPER(a.sku_group) LIKE \'MP-SS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-SD%\' THEN \'Jeans\' WHEN UPPER(a.sku_group) LIKE \'MP-ST%\' THEN \'T-Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-OS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-CS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-SO%\' THEN \'Cargo Pants\' WHEN UPPER(a.sku_group) LIKE \'MP-SR%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'MP-QS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-SC%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'MP-SJ%\' THEN \'Joggers & Trackpants\' WHEN UPPER(a.sku_group) LIKE \'MP-SS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-SD%\' THEN \'Jeans\' WHEN UPPER(a.sku_group) LIKE \'MP-ST%\' THEN \'T-Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-OS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-CS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-SO%\' THEN \'Cargo Pants\' WHEN UPPER(a.sku_group) LIKE \'MP-SR%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'MP-QS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'MP-SC%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'MP-SJ%\' THEN \'Joggers & Trackpants\' WHEN UPPER(a.sku_group) LIKE \'4MBGSS%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'4MBGSR%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'4MBGSD%\' THEN \'Jeans\' WHEN UPPER(a.sku_group) LIKE \'4MBGST%\' THEN \'T-Shirts\' WHEN UPPER(a.sku_group) LIKE \'4MSWHC%\' THEN \'Hoodies\' WHEN UPPER(a.sku_group) LIKE \'4MSWC%\' THEN \'Sweatshirts\' WHEN UPPER(a.sku_group) LIKE \'4MSKC%\' THEN \'Jackets\' WHEN UPPER(a.sku_group) LIKE \'4MCRD%\' THEN \'Jeans\' WHEN UPPER(a.sku_group) LIKE \'4MCRT%\' THEN \'T-Shirts\' WHEN UPPER(a.sku_group) LIKE \'4MLRT%\' THEN \'Shirts\' WHEN UPPER(a.sku_group) LIKE \'4MLXT%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'4MLXD%\' THEN \'Jeans\' WHEN UPPER(a.sku_group) LIKE \'SH00%\' THEN \'Shoes\' WHEN UPPER(a.sku_group) LIKE \'4MSS%\' THEN \'T-Shirts\' WHEN UPPER(a.sku_group) LIKE \'4MSR%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'4MSO%\' THEN \'Cargo Pants\' WHEN UPPER(a.sku_group) LIKE \'4MSC%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'4MSK%\' THEN \'Jackets\' WHEN UPPER(a.sku_group) LIKE \'4MSD%\' THEN \'Shorts\' WHEN UPPER(a.sku_group) LIKE \'4MSH%\' THEN \'Shorts\' WHEN UPPER(a.sku_group) LIKE \'4MSP%\' THEN \'Pyjamas\' WHEN UPPER(a.sku_group) LIKE \'4MSWH%\' THEN \'Hoodies\' WHEN UPPER(a.sku_group) LIKE \'4MSWS%\' THEN \'Sweatshirts\' WHEN UPPER(a.sku_group) LIKE \'4MSW%\' THEN \'Sweatshirts\' WHEN UPPER(a.sku_group) LIKE \'4MTP%\' THEN \'Joggers & Trackpants\' WHEN UPPER(a.sku_group) LIKE \'4MSJ%\' THEN \'Joggers & Trackpants\' WHEN UPPER(a.sku_group) LIKE \'4MBZ%\' THEN \'Blazers\' WHEN UPPER(a.sku_group) LIKE \'4MST%\' THEN \'T-Shirts\' WHEN UPPER(a.sku_group) LIKE \'4MOS%\' THEN \'Overshirt\' WHEN UPPER(a.sku_group) LIKE \'4MKP%\' THEN \'Trousers\' WHEN UPPER(a.sku_group) LIKE \'4MBL%\' THEN \'Belts\' END ) AS category, b.fit AS fit, b.collar AS collar, b.print_design AS print_design, a.PUTAWAY_UPDATED AS month, SUM(a.PUTAWAY_COMPLETED_QUANTITY) AS actual_qty FROM actual_pre AS a LEFT JOIN (Select * from snitch_db.maplemonk.metafields_data) AS b ON a.sku_group = b.sku_group GROUP BY 1, 2, 3, 4, 5, 6,7 ) , summary as ( Select SKU_GROUP, max(L1_CATEGORY) as L1_CATEGORY, max(CATEGORY) as CATEGORY, max(FIT) as FIT, max(COLLAR) as COLLAR, max(PRINT_DESIGN) as PRINT_DESIGN, max(MONTH) as MONTH, sum(ACTUAL_QTY) as Inward_Qty from actual_plan where month >=\'2025-08-01\' group by 1) , Images_1 as ( SELECT sku_group, image_url FROM ( SELECT UPPER( LEFT( variant.value:sku::STRING, LENGTH(variant.value:sku::STRING) - POSITION(\'-\' IN REVERSE(variant.value:sku::STRING)) ) ) AS sku_group, image.value:\"preview\":\"image\":\"url\"::STRING AS image_url, ROW_NUMBER() OVER ( PARTITION BY UPPER( LEFT( variant.value:sku::STRING, LENGTH(variant.value:sku::STRING) - POSITION(\'-\' IN REVERSE(variant.value:sku::STRING)) ) ) ORDER BY image.index ) AS rn FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql t, LATERAL FLATTEN(input => PARSE_JSON(t.media)) AS image, LATERAL FLATTEN(input => PARSE_JSON(t.variants)) AS variant WHERE image.value:\"mediaContentType\"::STRING = \'IMAGE\' ) WHERE rn = 1), Current_1 as ( Select Sku_group, sum(sellable_inventory) as Current_inventory, max(sku_class) as sku_class, max(STATUS) as STATUS, max(LIVE_DATE) as LIVE_DATE, max(NUM_SIZE_AVAILABLE) as NUM_SIZE_AVAILABLE, sum(sales_last_30_days) as sales_last_30_days, SUM( (CASE WHEN S_UNITS >= 5 THEN 1 else 0 END) + (CASE WHEN M_UNITS >= 5 THEN 1 else 0 END) + (CASE WHEN L_UNITS >= 5 THEN 1 else 0 END) + (CASE WHEN XL_UNITS >= 5 THEN 1 else 0 END) ) AS num_of_size_of_offline_4pivot, SUM( (CASE WHEN M_UNITS >= 5 THEN 1 else 0 END) + (CASE WHEN L_UNITS >= 5 THEN 1 else 0 END) + (CASE WHEN XL_UNITS >= 5 THEN 1 else 0 END) ) AS num_of_size_of_offline_3pivot, from snitch_db.maplemonk.availability_master_v2 group by 1 ), Offline as ( Select Upper(Sku_group) as Sku_group , sum(fresh_inventory) as inventory, max(material_new) as Material, max(COLOR) as COLOR, max(STYLE) as STYLE, sum(jit_qty) as jit_qty from snitch_db.maplemonk.offline_master group by 1 ) Select a.*, b.CURRENT_INVENTORY, c.inventory as Offline_Inventory, c.jit_qty, c.Material, c.COLOR, c.STYLE, b.NUM_SIZE_AVAILABLE, b.SKU_CLASS, b.LIVE_DATE, b.sales_last_30_days, b.num_of_size_of_offline_4pivot, b.num_of_size_of_offline_3pivot, Case when b.SKU_CLASS in (\'Not-Cataloged\',\'4-New\',\'4-New-Not-Sold\') then \'New\' when b.STATUS in (\'draft\') then \'New\' when CURRENT_DATE - b.LIVE_DATE <=45 then \'New\' else \'Repeat\' end as Type, k.image_url, CASE WHEN lower(category) = \'shirts\' THEN CASE WHEN TRIM(LOWER(print_design)) IN (\'geometric, floral, printed\', \'printed, geometric\', \'abstract, embroidered\', \'geometric\', \'geometric, checks, printed\', \'printed, abstract\', \'abstract\', \'graphic print\', \'floral, animal print, abstract, printed\', \'geometric, abstract, printed\', \'geometric, embroidered, printed\', \'colourblocked, printed\', \'floral, printed\', \'geometric, printed\', \'abstract, marble, printed\', \'abstract, floral, printed\', \'animal print\', \'printed, tie & dye\', \'abstract, printed\', \'printed\', \'abstract, tie & dye, printed\', \'printed, floral\', \'colourblocked\', \'printed, polka dots\', \'floral\', \'abstract, geometric, printed\', \'printed, animal print\', \'tie & dye\', \'printed, graphic print\') THEN \'Printed\' WHEN TRIM(LOWER(print_design)) IN (\'embellished\', \'self-embroidered\', \'applique\', \'embroidered\') THEN \'Embroided\' WHEN TRIM(LOWER(print_design)) IN (\'plaid, checked\', \'checks, abstract\', \'self-design, geometric\', \'checks\', \'gingham\', \'checks, printed\', \'checks, stripes\', \'gingham, checks\', \'checks, geometric\', \'checks, floral, abstract, printed\') THEN \'Checks\' WHEN TRIM(LOWER(print_design)) IN (\'textured, stripes\', \'stripes\', \'stripes, printed\') THEN \'Stripes\' WHEN TRIM(LOWER(print_design)) IN (\'solid\', \'plain\') THEN \'Solid\' WHEN TRIM(LOWER(print_design)) IN (\'self-design, stripes\', \'self-design, tie & dye\', \'self-design, textured, plain\', \'textured, stripe\', \'textured, self-design\', \'self-design, textured\', \'textured\', \'self-design\', \'self-deign\', \'textured, geometric, self-design\', \'sefl-design\', \'self design\') THEN \'Textured\' WHEN TRIM(LOWER(print_design)) IN (\'college wear, casual wear\', \'knitted\',\'jacquard\',\'others\') THEN \'Others\' ELSE print_design END WHEN lower(category) = \'t-shirts\' THEN CASE WHEN TRIM(LOWER(print_design)) IN (\'printed, geometric\', \'printed\', \'graphic print, abstract, printed\', \'tie & dye\', \'geometric\', \'printed, graphic print\', \'graphic print\', \'printed, abstract\', \'abstract\', \'ombre\', \'animal print\', \'embroidered, graphic print\', \'abstract, printed\', \'graphic print, embroidered\', \'printed, abstract, printed\', \'graphic print,\', \'printed, polka dots\', \'camouflage\', \'printed, floral\', \'floral\', \'printed, animal print\', \'tye & dye\', \'graphic print, embroidered, printed\') THEN \'Graphic Printed\' WHEN TRIM(LOWER(print_design)) IN (\'solid\', \'plain\') THEN \'Plain\' WHEN TRIM(LOWER(print_design)) IN (\'textured, stripes\', \'self-design, textured, plain\', \'textured, self-design\', \'textured\', \'self-design, textured\', \'self-design\', \'self-design, knitted\') THEN \'Textured\' WHEN TRIM(LOWER(print_design)) IN (\'stripes, textured\', \'stripes\', \'stripes, colourblocked\') THEN \'Stripes\' WHEN TRIM(LOWER(print_design)) IN (\'embellished\', \'colorblocked\', \'embellished, printed\', \'colourblocked\', \'embroidered\', \'acid washed\',\'jacquard\',\'others\') THEN \'Others\' ELSE print_design END ELSE print_design END as print_design_n, CASE WHEN a.sku_group IN ( \'4MST2242-01\',\'4MSS2623-02\',\'4MSS3468-01\',\'4MSS1052-01\',\'4MSS1813-01\',\'4MSS1813-09\',\'4MSR5177-01\',\'4MST2242-03\', \'4MSS3208-07\',\'4MSS1052-03\',\'4MSS1813-08\',\'4MSS2623-04\',\'4MSS2513-04\',\'4MSR5194-03\',\'4MSR5163-02\',\'4MST2299-01\', \'4MSR5163-05\',\'4MSS3387-06\',\'4MSS3036-05\',\'4MSS1813-05\',\'4MSR5163-01\',\'4MST2201-03\',\'4MST2418-02\',\'4MSS3036-01\', \'4MSR5163-06\',\'4MSR5194-01\',\'4MSS3208-01\',\'4MSR5163-03\',\'4MSS3563-02\',\'4MSD3653-02\',\'4MSD3517-01\',\'4MST2242-04\', \'4MSS2624-03\',\'4MSS3563-07\',\'4MSS3387-01\',\'4MSC4015-06\',\'4MSS1813-07\',\'4MSS1216-11\',\'4MSS3012-01\',\'4MSS1216-07\', \'4MSS3307-05\',\'4MST2228-03\',\'4MSR5116-01\',\'4MSS2624-02\',\'4MSR5163-04\',\'4MSS3155-02\',\'4MSS1813-04\',\'4MST2068-02\', \'4MST2418-03\',\'4MSD3864-01\',\'4MSS2363-06\',\'4MSS2367-04\',\'4MSS3208-03\',\'4MSS3157-01\',\'4MSS2438-02\',\'4MSS3387-05\', \'4MSS1813-06\',\'4MSS2623-03\',\'4MSC4015-05\',\'4MSS3307-03\',\'4MSR5172-01\',\'4MSS3208-06\',\'4MSS3563-03\',\'4MSS2068-06\', \'4MSS1813-10\',\'4MST2180-01\',\'4MSO4571-02\',\'4MSR5079-02\',\'4MSS2998-07\',\'4MSD3719-01\',\'4MST2180-04\',\'4MSS1813-03\', \'4MSR5172-02\',\'4MSS2335-05\',\'4MST2450-04\',\'4MSS2335-09\',\'4MST2178-02\',\'4MSS1813-02\',\'4MSS3563-05\',\'4MSS1216-08\', \'4MST2242-02\',\'4MSS3012-02\',\'4MST2228-04\',\'4MSS3307-04\',\'4MSS1052-02\',\'4MSS2998-05\',\'4MST2178-04\',\'4MSS2438-05\', \'4MSC4015-04\',\'4MSS3012-03\',\'4MSR5013-01\',\'4MSS1052-04\',\'4MSS2998-09\',\'4MSD3514-01\',\'4MST2180-03\',\'4MSS2998-02\', \'4MSS3194-01\',\'4MSD3741-01\',\'4MSD3667-05\',\'4MSS2998-06\' ) THEN \'Online NOOS\' WHEN a.sku_group IN ( \'4MSN1310-03E\',\'4MSS3976A\',\'4MSS3976B\',\'4MSS3976C\',\'4MCR1004A\',\'4MCR1004B\',\'4MSN1310-03F\',\'4MSN1310-03G\', \'4MSN1310-03H\',\'4MSN1310-03I\',\'4MSN1310-03J\',\'4MST